param([Parameter(Mandatory=$true)][string]$JobRoot,[string]$RepositoryRoot,[string]$AttemptId='oracle-v1')
$ErrorActionPreference='Stop';if(-not$RepositoryRoot){$RepositoryRoot=Join-Path $JobRoot 'repo'}
if(-not([IO.Path]::GetFullPath($JobRoot)).StartsWith('D:\CodexLab\')){throw'job root'}
$s=Join-Path $RepositoryRoot 'src\fg_dynamic_module13\rtx_oracle.cpp';$m=Join-Path $JobRoot 'inputs\cu-module-000013.bin';$out=Join-Path $JobRoot "output\$AttemptId";if(Test-Path $out){throw'exists'};New-Item -ItemType Directory -Path "$out\build"|Out-Null
$cuda=if($env:CUDA_PATH){$env:CUDA_PATH}else{'C:\Program Files\NVIDIA GPU Computing Toolkit\CUDA\v13.3'};$vs=Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio\Installer\vswhere.exe';$i=&$vs -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath;$vc=Join-Path $i 'VC\Auxiliary\Build\vcvars64.bat';$exe="$out\build\probe.exe";$obj="$out\build\probe.obj";$log="$out\build\compile.log";$cmd='"{0}" >nul && cl /nologo /std:c++20 /EHsc /MD /W4 /WX /I"{1}" /Fo"{2}" /c "{3}" >"{4}" 2>&1 && link /nologo /OUT:"{5}" "{2}" "{6}" bcrypt.lib >>"{4}" 2>&1'-f$vc,(Join-Path $cuda 'include'),$obj,$s,$log,$exe,(Join-Path $cuda 'lib\x64\cuda.lib');&$env:ComSpec /d /s /c $cmd;if($LASTEXITCODE){throw'compile'}
$rs=@();foreach($r in @('720p','1080p','1440p','4k')){foreach($p in @('reset','generated')){foreach($c in @('equal-high-tie','priority-collision')){foreach($z in @('a5','5a')){foreach($q in @('a','b')){$id="$r-$p-$c-poison-$z-process-$q";$d=Join-Path $out $id;New-Item -ItemType Directory -Path $d|Out-Null;$mde=if($z-eq'a5'-and$q-eq'a'){'full'}else{'hash-only'};$x=Start-Process $exe -ArgumentList @($m,$d,$id,$z,$r,$p,$c,$mde) -Wait -PassThru -NoNewWindow -RedirectStandardOutput "$d\stdout.log" -RedirectStandardError "$d\stderr.log";if($x.ExitCode){throw"run $id"};$v=Get-Content "$d\run-receipt.json" -Raw|ConvertFrom-Json;if($v.result-ne'pass'){throw"receipt $id"};$rs+=$v}}}}}
$pids=@($rs.process_id|sort -Unique);if($pids.Count-ne64){throw'pids'};$rec=[ordered]@{schema='neuralstudio.fg.dynamic-module13-rig.v1';job_id=Split-Path -Leaf $JobRoot;module_sha256=(Get-FileHash $m -Algorithm SHA256).Hash.ToLowerInvariant();source_sha256=(Get-FileHash $s -Algorithm SHA256).Hash.ToLowerInvariant();binary_sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant();run_count=64;fresh_process_count=64;true_typed_cuda_arrays=$true;repeat_and_poison_exact=$true;expected_or_captured_output_ingress=$false;address_fields_recorded=$false;result='pass'};$u=New-Object Text.UTF8Encoding($false);$rp="$out\rig-receipt.json";[IO.File]::WriteAllText($rp,(($rec|ConvertTo-Json -Depth 5)+"`n"),$u);Write-Host "rig_receipt_sha256=$((Get-FileHash $rp -Algorithm SHA256).Hash.ToLowerInvariant())";Write-Host result=pass
